//! IPC contract for the UI (FUNCTIONAL_SPEC §2, §4; docs/STACK.md "IPC layer").
//!
//! Commands are schema-driven: every command and DTO carries `specta::Type` and
//! TypeScript bindings are generated by tauri-specta at debug build time
//! (../ui/src/bindings.ts) - hand-written bindings are not allowed.
//!
//! Commands run as async fns: sync Tauri commands execute on the main thread,
//! so long loading (§2 non-blocking requirement) must not be sync.

use serde::Serialize;

use logviewer_core::format::Format;
use logviewer_core::parser::Level;
use logviewer_core::workspace::FileModel;

/// Shared app state: the currently loaded file, if any.
pub type FileState = std::sync::Mutex<Option<FileModel>>;

pub fn new_file_state() -> FileState {
  std::sync::Mutex::new(None)
}

// ---------------------------------------------------------------- DTOs

// spec interpretation: levels travel as lowercase long names ("critical",
// "error", "warning", "msg", "debug", "trace"); short codes are a UI detail.
pub fn level_name(level: Level) -> &'static str {
  match level {
    Level::Critical => "critical",
    Level::Error => "error",
    Level::Warning => "warning",
    Level::Msg => "msg",
    Level::Debug => "debug",
    Level::Trace => "trace",
  }
}

pub fn format_name(format: Format) -> &'static str {
  match format {
    Format::Ksiva => "ksiva",
    Format::Plain => "plain",
  }
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct CategoryCount {
  pub path: String,
  pub count: u32,
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct LevelCount {
  pub level: String,
  pub count: u32,
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct LoadResult {
  /// Detected format: "ksiva" or "plain" (§3).
  pub format: String,
  pub line_count: u32,
  pub categories: Vec<CategoryCount>,
  pub levels: Vec<LevelCount>,
  /// Load time in milliseconds (diagnostics; §16 monitoring).
  pub load_ms: u32,
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct RowDto {
  /// 1-based line number in the source file.
  pub line_no: u32,
  pub time_display: String,
  pub category: String,
  pub level: String,
  pub message: String,
  // spec interpretation: the raw line travels as lossy UTF-8 text; raw bytes
  // with invalid encoding cannot be represented in the webview strings anyway.
  pub raw: String,
}

pub fn level_order() -> [Level; 6] {
  [
    Level::Critical,
    Level::Error,
    Level::Warning,
    Level::Msg,
    Level::Debug,
    Level::Trace,
  ]
}

pub fn to_load_result(model: &FileModel, load_ms: u32) -> LoadResult {
  LoadResult {
    format: format_name(model.format()).to_owned(),
    line_count: model.line_count() as u32,
    categories: model
      .categories()
      .map(|(path, count)| CategoryCount {
        path: path.to_owned(),
        count: count as u32,
      })
      .collect(),
    // §11 counters: fixed level order, zero counts included.
    levels: level_order()
      .into_iter()
      .map(|level| LevelCount {
        level: level_name(level).to_owned(),
        count: model.level_count(level) as u32,
      })
      .collect(),
    load_ms: load_ms,
  }
}

pub fn to_row_dto(row: &logviewer_core::parser::Row) -> RowDto {
  RowDto {
    line_no: row.line_no,
    time_display: row.time_display.clone(),
    category: row.category.clone(),
    level: level_name(row.level).to_owned(),
    message: row.message.clone(),
    raw: String::from_utf8_lossy(&row.raw).into_owned(),
  }
}

// ---------------------------------------------------------------- commands

/// Load a file in the background and make it the active model (§2).
/// Loading must not block the UI: this is an async command.
#[tauri::command]
#[specta::specta]
pub async fn load_file(
  path: String,
  state: tauri::State<'_, FileState>,
) -> Result<LoadResult, String> {
  let (model, stats) = logviewer_core::workspace::FileModel::load_path(std::path::Path::new(&path))
    .map_err(|e| format!("cannot open {path}: {e}"))?;
  let result = to_load_result(&model, stats.elapsed.as_millis() as u32);
  let mut guard = state.lock().map_err(|_| "state poisoned".to_owned())?;
  *guard = Some(model);
  Ok(result)
}

/// A window of rows, 0-based offset over line numbers (§4 virtual scrolling).
#[tauri::command]
#[specta::specta]
pub async fn get_rows(
  offset: u32,
  limit: u32,
  state: tauri::State<'_, FileState>,
) -> Result<Vec<RowDto>, String> {
  let guard = state.lock().map_err(|_| "state poisoned".to_owned())?;
  Ok(
    guard
      .as_ref()
      .map(|model| {
        model
          .rows_slice(offset as usize, limit as usize)
          .iter()
          .map(to_row_dto)
          .collect()
      })
      .unwrap_or_default(),
  )
}

// ---------------------------------------------------------------- tests

#[cfg(test)]
mod tests {
  use super::*;

  fn temp_file(name: &str, data: &[u8]) -> std::path::PathBuf {
    let path = std::env::temp_dir().join(format!("lv_ipc_{name}"));
    std::fs::write(&path, data).unwrap();
    path
  }

  #[test]
  fn load_result_shape_and_row_dto() {
    let path = temp_file(
      "shape.log",
      concat!(
        "2024-01-01T10:00:00.000 app/main LOG_MSG hello\n",
        "2024-01-01T10:00:01.000 app [LOG_ERR] bracketed\n",
      )
      .as_bytes(),
    );
    let (model, _) =
      FileModel::load_path(&path).expect("temp file loads");
    let result = to_load_result(&model, 7);
    assert_eq!(result.format, "ksiva");
    assert_eq!(result.line_count, 2);
    assert_eq!(result.load_ms, 7);
    assert_eq!(
      result
        .categories
        .iter()
        .map(|c| c.path.as_str())
        .collect::<Vec<_>>(),
      vec!["app", "app/main"]
    );
    assert_eq!(
      result
        .levels
        .iter()
        .map(|l| (l.level.as_str(), l.count))
        .collect::<Vec<_>>(),
      vec![
        ("critical", 0),
        ("error", 1),
        ("warning", 0),
        ("msg", 1),
        ("debug", 0),
        ("trace", 0)
      ]
    );
    let row = to_row_dto(model.row(1).expect("row 2 exists"));
    assert_eq!(row.line_no, 2);
    assert_eq!(row.level, "error");
    assert_eq!(row.message, "bracketed");
    assert_eq!(row.category, "app");
    assert_eq!(row.raw, "2024-01-01T10:00:01.000 app [LOG_ERR] bracketed");
  }

  #[test]
  fn empty_state_get_rows_is_empty_vec() {
    let state = new_file_state();
    let guard = state.lock().unwrap();
    assert!(guard.as_ref().is_none());
  }
}
